# Pulumi ComponentResource: Service + Bucket + DB

Here's a complete implementation of a ComponentResource wrapping S3, RDS, and IAM for dev/prod environments.

## Project Structure

```
.
├── Pulumi.yaml
├── Pulumi.dev.yaml
├── Pulumi.prod.yaml
├── package.json
├── tsconfig.json
├── index.ts
└── components/
    └── serviceStack.ts
```

## Component Definition

**`components/serviceStack.ts`**

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

export interface ServiceStackArgs {
  environmentType: "dev" | "prod";
  bucketName: string;
  dbInstanceClass: string;
  dbAllocatedStorage: number;
  dbEngineVersion?: string;
  dbBackupRetentionPeriod?: number;
  enableReplication?: boolean;
  replicationRegion?: string;
  tags?: Record<string, string>;
}

export class ServiceStack extends pulumi.ComponentResource {
  public readonly bucket: aws.s3.Bucket;
  public readonly bucketVersioning: aws.s3.BucketVersioningV2;
  public readonly dbInstance: aws.rds.Instance;
  public readonly iamRole: aws.iam.Role;
  public readonly iamRolePolicy: aws.iam.RolePolicy;

  constructor(
    name: string,
    args: ServiceStackArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("service:components:ServiceStack", name, {}, opts);

    const config = new pulumi.Config();
    const defaultTags = {
      Environment: args.environmentType,
      Stack: pulumi.getStack(),
      ManagedBy: "Pulumi",
      ...args.tags,
    };

    // ─────────────────────────────────────
    // S3 Bucket with Versioning & Encryption
    // ─────────────────────────────────────

    this.bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: args.bucketName,
        forceDestroy: args.environmentType === "dev", // Allow deletion in dev
        tags: defaultTags,
      },
      { parent: this }
    );

    // Enable versioning
    this.bucketVersioning = new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: this.bucket.id,
        versioningConfiguration: {
          status: "Enabled",
        },
      },
      { parent: this }
    );

    // Server-side encryption (AES-256)
    new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-encryption`,
      {
        bucket: this.bucket.id,
        rules: [
          {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        ],
      },
      { parent: this }
    );

    // Block public access
    new aws.s3.BucketPublicAccessBlock(
      `${name}-pab`,
      {
        bucket: this.bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      { parent: this }
    );

    // Optional: cross-region replication for prod
    if (args.enableReplication && args.replicationRegion) {
      const replicationRoleArn = pulumi
        .output(
          aws.iam.getPolicyDocument({
            statements: [
              {
                effect: "Allow",
                principals: [
                  {
                    type: "Service",
                    identifiers: ["s3.amazonaws.com"],
                  },
                ],
                actions: ["sts:AssumeRole"],
              },
            ],
          })
        )
        .then((doc) => {
          const role = new aws.iam.Role(
            `${name}-replication-role`,
            {
              assumeRolePolicy: doc.json,
            },
            { parent: this }
          );
          new aws.iam.RolePolicy(
            `${name}-replication-policy`,
            {
              role: role.id,
              policy: pulumi.output(
                aws.iam.getPolicyDocument({
                  statements: [
                    {
                      effect: "Allow",
                      actions: [
                        "s3:GetReplicationConfiguration",
                        "s3:ListBucket",
                      ],
                      resources: [this.bucket.arn],
                    },
                    {
                      effect: "Allow",
                      actions: [
                        "s3:GetObjectVersionForReplication",
                        "s3:GetObjectVersionAcl",
                      ],
                      resources: [pulumi.concat(this.bucket.arn, "/*")],
                    },
                    {
                      effect: "Allow",
                      actions: ["s3:ReplicateObject", "s3:ReplicateDelete"],
                      resources: [
                        pulumi.concat(
                          "arn:aws:s3:::bucket-",
                          args.replicationRegion,
                          "/*"
                        ),
                      ],
                    },
                  ],
                })
              ).then((doc) => doc.json),
            },
            { parent: this }
          );
          return role.arn;
        });
    }

    // ─────────────────────────────────────
    // RDS PostgreSQL Instance
    // ─────────────────────────────────────

    const dbPassword = config.requireSecret("dbPassword");
    const engineVersion = args.dbEngineVersion || "16.1";
    const backupRetention = args.dbBackupRetentionPeriod || 7;

    this.dbInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        identifier: `${name}-db-${args.environmentType}`,
        engine: "postgres",
        engineVersion: engineVersion,
        instanceClass: args.dbInstanceClass,
        allocatedStorage: args.dbAllocatedStorage,
        dbName: "appdb",
        username: "postgres",
        password: dbPassword,

        // Security & Protection
        skipFinalSnapshot: args.environmentType === "dev",
        finalSnapshotIdentifier: args.environmentType === "prod"
          ? pulumi.interpolate`${name}-db-final-snapshot-${Date.now()}`
          : undefined,
        deletionProtection: args.environmentType === "prod",

        // Backup & Maintenance
        backupRetentionPeriod: backupRetention,
        backupWindow: "03:00-04:00",
        maintenanceWindow: "mon:04:00-mon:05:00",

        // High Availability (prod)
        multiAz: args.environmentType === "prod",

        // Encryption
        storageEncrypted: true,
        kmsKeyId: args.environmentType === "prod"
          ? new aws.kms.Key(`${name}-rds-key`, {
              description: `KMS key for ${name} RDS encryption`,
              deletionWindowInDays: 10,
              tags: defaultTags,
            }, { parent: this }).arn
          : undefined,

        // Network
        publiclyAccessible: false,
        skipFinalSnapshot: args.environmentType === "dev",

        tags: defaultTags,
      },
      { parent: this }
    );

    // ─────────────────────────────────────
    // IAM Role for Service Accounts
    // ─────────────────────────────────────

    const trustPolicy = pulumi
      .output(
        aws.iam.getPolicyDocument({
          statements: [
            {
              effect: "Allow",
              principals: [
                {
                  type: "AWS",
                  identifiers: ["arn:aws:iam::ACCOUNT_ID:root"], // Replace with actual account
                },
              ],
              actions: ["sts:AssumeRole"],
            },
            // OIDC provider for EKS (if applicable)
            {
              effect: "Allow",
              principals: [
                {
                  type: "Federated",
                  identifiers: [
                    "arn:aws:iam::ACCOUNT_ID:oidc-provider/oidc.eks.REGION.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E",
                  ],
                },
              ],
              actions: ["sts:AssumeRoleWithWebIdentity"],
              conditions: [
                {
                  test: "StringEquals",
                  variable:
                    "oidc.eks.REGION.amazonaws.com/id/EXAMPLED539D4633E53DE1B716D3041E:sub",
                  values: ["system:serviceaccount:default:app"],
                },
              ],
            },
          ],
        })
      )
      .then((doc) => doc.json);

    this.iamRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        name: `${name}-service-role-${args.environmentType}`,
        assumeRolePolicy: trustPolicy,
        tags: defaultTags,
      },
      { parent: this }
    );

    // Principle of Least Privilege
    const policyDocument = pulumi
      .output(
        aws.iam.getPolicyDocument({
          statements: [
            // S3 bucket access
            {
              effect: "Allow",
              actions: ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"],
              resources: [pulumi.concat(this.bucket.arn, "/*")],
            },
            {
              effect: "Allow",
              actions: ["s3:ListBucket"],
              resources: [this.bucket.arn],
            },
            // RDS database access (connection only)
            {
              effect: "Allow",
              actions: ["rds-db:connect"],
              resources: [
                pulumi.concat(
                  "arn:aws:rds:",
                  aws.getRegion().then((r) => r.name),
                  `:ACCOUNT_ID:db/${this.dbInstance.identifier}`
                ),
              ],
            },
          ],
        })
      )
      .then((doc) => doc.json);

    this.iamRolePolicy = new aws.iam.RolePolicy(
      `${name}-service-policy`,
      {
        role: this.iamRole.id,
        policy: policyDocument,
      },
      { parent: this }
    );

    // Register outputs
    this.registerOutputs({
      bucketName: this.bucket.id,
      bucketArn: this.bucket.arn,
      dbEndpoint: this.dbInstance.endpoint,
      dbPort: this.dbInstance.port,
      roleArn: this.iamRole.arn,
      roleName: this.iamRole.name,
    });
  }
}
```

## Main Stack

**`index.ts`**

```typescript
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";
import { ServiceStack } from "./components/serviceStack";

const stack = pulumi.getStack();
const config = new pulumi.Config();

// Parse environment from stack name
const environment = stack === "dev" ? "dev" : "prod";

// Read config values
const region = config.require("region");
const bucketName = config.require("bucketName");
const dbInstanceClass = config.require("dbInstanceClass");
const dbAllocatedStorage = config.getNumber("dbAllocatedStorage") || 20;
const enableReplication = config.getBoolean("enableReplication") || false;
const replicationRegion = config.get("replicationRegion");

const provider = new aws.Provider(stack, {
  region: region,
});

// Instantiate the ComponentResource
const serviceStack = new ServiceStack(
  `app-${environment}`,
  {
    environmentType: environment as "dev" | "prod",
    bucketName: bucketName,
    dbInstanceClass: dbInstanceClass,
    dbAllocatedStorage: dbAllocatedStorage,
    dbEngineVersion: "16.1",
    dbBackupRetentionPeriod: environment === "prod" ? 30 : 7,
    enableReplication: enableReplication,
    replicationRegion: replicationRegion,
    tags: {
      Project: "app",
      CostCenter: "engineering",
    },
  },
  { provider }
);

// Export outputs
export const bucketName_out = serviceStack.bucket.id;
export const bucketArn = serviceStack.bucket.arn;
export const dbEndpoint = serviceStack.dbInstance.endpoint;
export const dbPort = serviceStack.dbInstance.port;
export const dbName = serviceStack.dbInstance.dbName;
export const roleArn = serviceStack.iamRole.arn;
export const roleName = serviceStack.iamRole.name;
```

## Configuration Files

**`Pulumi.yaml`**

```yaml
name: service-stack
runtime: typescript
description: Reusable service stack with S3, RDS, and IAM
```

**`Pulumi.dev.yaml`**

```yaml
config:
  aws:region: us-east-1
  service-stack:region: us-east-1
  service-stack:bucketName: app-assets-dev-${AWS::AccountId}
  service-stack:dbInstanceClass: db.t3.micro
  service-stack:dbAllocatedStorage: 20
  service-stack:enableReplication: false
  service-stack:dbPassword:
    secure: AAAaABC... # Run `pulumi config set --secret dbPassword mypassword`
```

**`Pulumi.prod.yaml`**

```yaml
config:
  aws:region: us-east-1
  service-stack:region: us-east-1
  service-stack:bucketName: app-assets-prod-${AWS::AccountId}
  service-stack:dbInstanceClass: db.t3.medium
  service-stack:dbAllocatedStorage: 100
  service-stack:enableReplication: true
  service-stack:replicationRegion: us-west-2
  service-stack:dbPassword:
    secure: BBBbBBC... # Run `pulumi config set --secret dbPassword prodpassword`
```

